function bestDistinctWindow(nums: number[], k: number): number {
  let best = 0;
  for (let s = 0; s + k <= nums.length; s++) {
    const seen = new Set<number>();
    let sum = 0;
    for (let i = s; i < s + k; i++) { seen.add(nums[i]); sum += nums[i]; }
    if (seen.size === k) best = Math.max(best, sum);
  }
  return best;
}

