function bestDistinctWindow(nums: number[], k: number): number {
  const count = new Map<number, number>();
  let sum = 0, best = 0;
  for (let i = 0; i < nums.length; i++) {
    sum += nums[i];
    count.set(nums[i], (count.get(nums[i]) ?? 0) + 1);
    if (i >= k) {
      const out = nums[i - k];
      sum -= out;
      const c = count.get(out)! - 1;
      if (c === 0) count.delete(out); else count.set(out, c);
    }
    if (i >= k - 1 && count.size === k) best = Math.max(best, sum);
  }
  return best;
}

